// Extract message data from Meta WhatsApp webhook payload
const webhookData = $input.first().json;
const body = webhookData.body || webhookData;

let phoneNumber = '';
let messageText = '';
let messageId = '';
let contactName = '';
let metaTimestamp = '';

if (body.entry && body.entry[0] && body.entry[0].changes && body.entry[0].changes[0]) {
  const change = body.entry[0].changes[0];
  if (change.value && change.value.messages && change.value.messages[0]) {
    const msg = change.value.messages[0];
    phoneNumber = msg.from || '';
    messageId = msg.id || '';
    messageText = msg.text?.body || msg.button?.text || msg.interactive?.button_reply?.title || '';
    metaTimestamp = msg.timestamp || '';

    if (change.value.contacts && change.value.contacts[0]) {
      contactName = change.value.contacts[0].profile?.name || '';
    }
  }
}

// Skip status update webhooks (delivered, read) that have no message content
if (!phoneNumber || !messageText) {
  return [];
}

const sessionId = phoneNumber.replace(/[^0-9]/g, '');

return {
  json: {
    phoneNumber,
    sessionId,
    messageText,
    messageId,
    contactName,
    metaTimestamp,
    timestamp: new Date().toISOString()
  }
};

// Parse OpenRouter response and score lead
const openrouterResult = $input.first().json;
const aiResponse = openrouterResult.choices?.[0]?.message?.content || 'Sorry, I did not understand that.';
const req = $('Build OpenRouter Request').first().json;

const messageLower = (req.messageText || '').toLowerCase();

let leadScore = 'COLD';

// Detect contact info in CURRENT USER MESSAGE only (not history, not AI response)
let hasPhone = /\b\d{10}\b|\b0\d{2}[\s-]?\d{3}[\s-]?\d{4}\b|\b\+\d{1,3}\s?\d{6,}\b/.test(messageLower);
let hasEmail = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i.test(req.messageText || '');
let hasAddress = /\bstreet\b|\broad\b|\bavenue\b|\bdrive\b|\bplace\b|\bclose\b|\bblvd\b|\baddress\b|\bsuburb\b|\bunit\b|\bno\.?\s\d/.test(messageLower);
let hasName = !!(req.contactName && req.contactName.length > 0);

let hasContactInfo = hasPhone || hasEmail;

// Sign-up intent keywords — check USER MESSAGE ONLY (not AI response)
const signUpIntent = /sign\s*up|install|apply|get\s*started|proceed|go\s*ahead|sounds\s*good|interested|let'?s\s*do\s*it|how\s*do\s*i\s*sign|ready\s*to\s*sign|let'?s\s*get\s*this|want\s*to\s*sign|go\s*for\s*it|sounds\s*perfect|that'?s\s*perfect/.test(messageLower);

// HOT: Current message shows explicit sign-up intent AND provides new contact info
// OR: Current message shows sign-up intent AND user already has name (from Meta profile)
if (signUpIntent && (hasContactInfo || hasAddress || hasName)) {
  leadScore = 'HOT';
} else if (hasContactInfo || hasAddress || (/price|cost|how\s*much|install|when\s*can|interested|package|sign\s*up/.test(messageLower) && hasName)) {
  leadScore = 'WARM';
} else if (/fibre|internet|broadband|wifi|data|lte|starlink/.test(messageLower)) {
  leadScore = 'WARM';
}

// --- Objection Detection ---
let objectionType = null;
const objectionPatterns = [
  { type: 'price_too_high', regex: /too expensive|can'?t afford|price is too high|out of my budget|paying less|fibre costs too much|not worth the money|don'?t want another monthly expense|more than i expected|too pricey|can'?t afford it/ },
  { type: 'comparing_providers', regex: /still comparing|looking around|want to compare|getting other quotes|waiting for another provider|haven'?t decided|shopping around|checking other|comparing options/ },
  { type: 'need_to_think', regex: /i'?ll think about|let me decide|discuss it with|discuss with my family|i'?ll get back to you|i'?ll let you know|not today|need to think|let me think|think about it/ },
  { type: 'already_have_fibre', regex: /already have fibre|with another provider|already connected|don'?t need fibre|my internet is working|already got fibre|have internet already|current provider/ },
  { type: 'moving', regex: /i'?m moving|relocating|new address|changing houses|moving next month|moving soon|moving to|relocation/ }
];
for (const p of objectionPatterns) { if (p.regex.test(messageLower)) { objectionType = p.type; break; } }

// --- Escalation Detection ---
let needsEscalation = false;
const escalationRegex = /discount|negotiate|custom pricing|callback|speak to a consultant|speak to a human|speak to someone|contract negotiation|can you call me|get a call|manager|supervisor|check.*availability|check.*coverage|is fibre available|check if.*available|coverage at|available at my|available at that|available at the/;
if (escalationRegex.test(messageLower)) { needsEscalation = true; }

// --- Follow-up Detection ---
let followUpRequested = false;
let followUpDate = null;
const followUpRegex = /think about it|get back to you|let you know|let me decide|discuss it with|discuss with my family|not today|need to think|let me think/;
if (followUpRegex.test(messageLower)) {
  followUpRequested = true;
  const d = new Date(); d.setDate(d.getDate() + 3);
  followUpDate = d.toISOString().split('T')[0];
}

// Objection or escalation bumps COLD to WARM minimum
if ((objectionType || needsEscalation) && leadScore === 'COLD') { leadScore = 'WARM'; }

return {
  json: {
    phoneNumber: req.phoneNumber,
    sessionId: req.sessionId,
    contactName: req.contactName,
    incomingMessage: req.messageText,
    aiResponse: aiResponse,
    leadScore: leadScore,
    hasContactInfo: hasContactInfo,
    hasAddress: hasAddress,
    objectionType: objectionType,
    needsEscalation: needsEscalation,
    followUpRequested: followUpRequested,
    followUpDate: followUpDate,
    timestamp: req.timestamp
  }
};

